/*
 * Furrow — SAMPLE DATA
 *
 * Every number in this file is generated by the code below from a fixed seed.
 * None of it is a measurement, a model output or a result. It exists so the
 * dashboard can be built and reviewed before the real pipelines run.
 *
 * Each block names the real source that will replace it:
 *   history   -> NASA POWER, GPM IMERG (GPM_3IMERGDF v07), SMAP L4 (SPL4SMGP v8),
 *                MODIS MOD13Q1 v061
 *   futures   -> NASA NEX-GDDP-CMIP6 (DOI 10.7917/OFSG3345)
 *   soil      -> open soil map + soil test typed in by the farmer
 *   crops     -> FAO-56 (Allen et al. 1998) and local extension guides
 *   sensor    -> field node (ESP32, capacitive soil-moisture sensors)
 */

export type FamilyId = "cereal" | "legume" | "oilseed" | "fibre" | "fallow";
export type CropId = "riceDry" | "riceWet" | "wheat" | "maize" | "mustard" | "mung" | "lentil" | "jute" | "fallow";
export type CriterionId = "climate" | "water" | "soil" | "income";

export interface Crop {
  name: string; short: string; family: FamilyId; days: number; waterMm: number;
  rootM: number; heatC: number | null; residue: string;
}
export interface Rotation { id: string; name: string; years: CropId[][] }
export interface HistoryYear {
  year: number; tempAnom: number; rainMm: number; rainAnomPct: number; seasonDays: number;
  ndviAnom: number; soilMoisture: number | null; stressIndex: number;
}
export interface Scenario { id: string; label: string; note: string; color: string }
export interface Horizon { id: string; label: string; from: number; to: number; mid: number }
export interface Future { horizon: string; scenario: string; model: string; dT: number; dP: number; heatDays: number; drySpell: number }
export interface FanPoint { year: number; p10: number; p50: number; p90: number }
export type Score = Record<CriterionId, number> & { irrigationMm: number };
export interface SensorReading { day: number; node10: number; node30: number; smap: number }

function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(20261114);
const norm = () => (rand() + rand() + rand() + rand() - 2) / 0.5774;
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
const round = (v: number, d = 0) => { const p = 10 ** d; return Math.round(v * p) / p; };
const mean = (a: number[]) => a.reduce((s, v) => s + v, 0) / a.length;

export function quantile(arr: number[], q: number) {
  const s = [...arr].sort((a, b) => a - b);
  const i = (s.length - 1) * q, lo = Math.floor(i), hi = Math.ceil(i);
  return s[lo] + (s[hi] - s[lo]) * (i - lo);
}

