/* ---------- History, 2000–2025 ---------- */

const years: number[] = [];
for (let y = 2000; y <= 2025; y++) years.push(y);
const rawT = years.map((y) => 0.024 * (y - 2012.5) + norm() * 0.16);
const rawRain = years.map((y) => 1450 - 3.2 * (y - 2012.5) + norm() * 165);
const tMean = mean(rawT);
const rMean = mean(rawRain);

export const history: HistoryYear[] = years.map((y, i) => {
  const tempAnom = rawT[i] - tMean;
  const rainAnomMm = rawRain[i] - rMean;
  const ndviAnom = 0.00011 * rainAnomMm - 0.03 * tempAnom + norm() * 0.013;
  const stress = clamp(42 - 0.055 * rainAnomMm + 30 * tempAnom + norm() * 7, 3, 97);
  return {
    year: y,
    tempAnom: round(tempAnom, 2),
    rainMm: round(rawRain[i]),
    rainAnomPct: round((rainAnomMm / rMean) * 100, 1),
    seasonDays: round(143 - 0.28 * (y - 2012.5) + norm() * 3.5),
    ndviAnom: round(ndviAnom, 3),
    soilMoisture: y >= 2015 ? round(0.31 + 0.00009 * rainAnomMm + norm() * 0.01, 3) : null,
    stressIndex: round(stress),
  };
});

/* A year counts as flagged at or above stressThreshold, and as a poor crop year at or below ndviThreshold. */
export const backtest = { stressThreshold: 50, ndviThreshold: -0.015 };

/* ---------- Projections ---------- */

const modelDraws = Array.from({ length: 12 }, (_, i) => ({ id: "Model " + (i + 1), s: 0.7 + rand() * 0.7, p: norm() }));
export const models = modelDraws.map((m) => m.id);

const scenarioParams: Record<string, { slope: number; rainShift: number }> = {
  ssp245: { slope: 0.035, rainShift: 0.4 },
  ssp585: { slope: 0.058, rainShift: -0.6 },
};
export const scenarios: Scenario[] = [
  { id: "ssp245", label: "SSP2-4.5", note: "middle emissions", color: "#2a78d6" },
  { id: "ssp585", label: "SSP5-8.5", note: "very high emissions", color: "#eb6834" },
];
export const horizons: Horizon[] = [
  { id: "2030s", label: "2030s", from: 2030, to: 2039, mid: 2035 },
  { id: "2050s", label: "2050s", from: 2050, to: 2059, mid: 2055 },
];
const T2025 = 0.3;
export const baseline = { heatDays: 8, drySpell: 13 };

export const futures: Future[] = [];
horizons.forEach((h) => scenarios.forEach((sc) => modelDraws.forEach((m) => {
  const sp = scenarioParams[sc.id];
  const span = h.mid - 2025;
  const dT = T2025 + m.s * sp.slope * span + norm() * 0.04;
  const dP = m.p * 6 + (sp.rainShift * span) / 10;
  futures.push({
    horizon: h.id, scenario: sc.id, model: m.id,
    dT: round(dT, 2), dP: round(dP, 1),
    heatDays: round(clamp(baseline.heatDays + 7 * dT + norm() * 1.5, 0, 60), 1),
    drySpell: round(clamp(baseline.drySpell + 2.4 * dT - 0.3 * dP + norm() * 1.2, 3, 60), 1),
  });
})));

export const fan: Record<string, FanPoint[]> = {};
scenarios.forEach((sc) => {
  fan[sc.id] = [];
  for (let y = 2025; y <= 2060; y++) {
    const vals = modelDraws.map((m) => T2025 + m.s * scenarioParams[sc.id].slope * (y - 2025));
    fan[sc.id].push({ year: y, p10: round(quantile(vals, 0.1), 2), p50: round(quantile(vals, 0.5), 2), p90: round(quantile(vals, 0.9), 2) });
  }
});

/* ---------- Rotation scores: one per rotation per future, 0–100, higher is better ---------- */

export const scores: Record<string, Score[]> = {};
rotations.forEach((r) => {
  const p = rotationParams[r.id];
  scores[r.id] = futures.map((f) => {
    const stress = clamp(p.stress + p.heat * f.dT + p.dry * Math.max(0, -f.dP) + norm() * 3, 0, 100);
    const irrigationMm = clamp(p.irrig * (1 + 0.05 * f.dT - 0.006 * f.dP) + norm() * 20, 100, 1800);
    return {
      climate: round(100 - stress, 1),
      water: round(clamp(100 - ((irrigationMm - 300) / 1200) * 100, 0, 100), 1),
      soil: p.soil,
      income: round(clamp(p.income - 0.35 * (stress - p.stress), 0, 100), 1),
      irrigationMm: round(irrigationMm),
    };
  });
});

/* ---------- Field sensor: 14 days, every 6 hours ---------- */

export const sensor: SensorReading[] = [];
{
  let s10 = 0.27, s30 = 0.3;
  for (let i = 0; i < 56; i++) {
    const rain = i === 13 ? 0.09 : i === 38 ? 0.06 : 0;
    s10 = clamp(s10 + rain - 0.0045 + norm() * 0.002, 0.14, 0.42);
    s30 = clamp(s30 + rain * 0.45 - 0.002 + norm() * 0.001, 0.18, 0.4);
    sensor.push({ day: round(i / 4, 2), node10: round(s10, 3), node30: round(s30, 3), smap: round(s30 - 0.028 + norm() * 0.004, 3) });
  }
}
